import re

# Define keywords related to flight booking issues
booking_keywords = [
    'book', 'booking', 'booked', 'reservation', 'reserve', 'reserved',
    'purchase', 'purchased', 'buy', 'bought', 'ticket', 'tickets',
    'website', 'web site', 'online', 'app ', 'mobile',
    'checkout', 'check out', 'payment', 'pay ', 'charged',
    'confirm', 'confirmation', 'itinerary', 'cancel', 'cancellation',
    'change flight', 'modify', 'reschedule', 'rebook'
]

# Let me first count how many dialogs per company mention booking-related terms
def has_booking_keywords(dialog_text):
    dialog_lower = dialog_text.lower()
    for kw in booking_keywords:
        if kw in dialog_lower:
            return True
    return False

